using UnityEngine;
using UnityEditor;
using System.IO;

public class Bootstrap
{
    public static void Execute()
    {
        string projectRoot = Path.Combine(Application.dataPath, "..");
        
        CreateDir(Path.Combine(projectRoot, "Assets/Scripts/Systems"));
        CreateDir(Path.Combine(projectRoot, "Assets/Scripts/UI"));
        CreateDir(Path.Combine(projectRoot, "Assets/Editor"));

        // ResourceSystem
        Write(Path.Combine(projectRoot, "Assets/Scripts/Systems/ResourceSystem.cs"),
"using UnityEngine;\nusing System;\n\npublic class ResourceSystem : MonoBehaviour\n{\n    public static ResourceSystem Instance { get; private set; }\n    public float FocusPoints { get; private set; } = 0f;\n    public event Action<float> OnFocusPointsChanged;\n\n    void Awake()\n    {\n        if (Instance != null && Instance != this) { Destroy(gameObject); return; }\n        Instance = this;\n    }\n\n    public void AddFocusPoints(float amount)\n    {\n        FocusPoints += amount;\n        OnFocusPointsChanged?.Invoke(FocusPoints);\n    }\n}\n");

        // FocusSystem
        Write(Path.Combine(projectRoot, "Assets/Scripts/Systems/FocusSystem.cs"),
"using UnityEngine;\nusing System;\n\npublic class FocusSystem : MonoBehaviour\n{\n    public static FocusSystem Instance { get; private set; }\n    public float focusDurationMinutes = 25f;\n    public float focusCompletionReward = 100f;\n    public float TimeRemaining { get; private set; }\n    public bool IsRunning { get; private set; } = false;\n    public bool IsCompleted { get; private set; } = false;\n    public event Action<float, float> OnTimerTick;\n    public event Action OnFocusCompleted;\n    public event Action<bool> OnRunningChanged;\n    private float totalDuration;\n\n    void Awake()\n    {\n        if (Instance != null && Instance != this) { Destroy(gameObject); return; }\n        Instance = this;\n    }\n\n    void Start() { ResetTimer(); }\n\n    void Update()\n    {\n        if (!IsRunning) return;\n        TimeRemaining -= Time.deltaTime;\n        OnTimerTick?.Invoke(TimeRemaining, totalDuration);\n        if (TimeRemaining <= 0f)\n        {\n            TimeRemaining = 0f;\n            IsRunning = false;\n            IsCompleted = true;\n            OnRunningChanged?.Invoke(false);\n            OnFocusCompleted?.Invoke();\n            ResourceSystem.Instance.AddFocusPoints(focusCompletionReward);\n        }\n    }\n\n    public void StartTimer()\n    {\n        if (IsCompleted) ResetTimer();\n        IsRunning = true;\n        OnRunningChanged?.Invoke(true);\n    }\n\n    public void PauseTimer()\n    {\n        IsRunning = false;\n        OnRunningChanged?.Invoke(false);\n    }\n\n    public void ToggleTimer()\n    {\n        if (IsRunning) PauseTimer();\n        else StartTimer();\n    }\n\n    public void ResetTimer()\n    {\n        totalDuration = focusDurationMinutes * 60f;\n        TimeRemaining = totalDuration;\n        IsRunning = false;\n        IsCompleted = false;\n        OnRunningChanged?.Invoke(false);\n        OnTimerTick?.Invoke(TimeRemaining, totalDuration);\n    }\n}\n");

        // IdleSystem
        Write(Path.Combine(projectRoot, "Assets/Scripts/Systems/IdleSystem.cs"),
"using UnityEngine;\n\npublic class IdleSystem : MonoBehaviour\n{\n    public static IdleSystem Instance { get; private set; }\n    public float baseIncomePerSecond = 1f;\n    public float focusMultiplier = 3f;\n    private float accumulator = 0f;\n\n    void Awake()\n    {\n        if (Instance != null && Instance != this) { Destroy(gameObject); return; }\n        Instance = this;\n    }\n\n    void Update()\n    {\n        float rate = baseIncomePerSecond;\n        if (FocusSystem.Instance != null && FocusSystem.Instance.IsRunning)\n            rate *= focusMultiplier;\n        accumulator += rate * Time.deltaTime;\n        if (accumulator >= 1f)\n        {\n            float points = Mathf.Floor(accumulator);\n            accumulator -= points;\n            ResourceSystem.Instance.AddFocusPoints(points);\n        }\n    }\n\n    public float GetCurrentRate()\n    {\n        float rate = baseIncomePerSecond;\n        if (FocusSystem.Instance != null && FocusSystem.Instance.IsRunning)\n            rate *= focusMultiplier;\n        return rate;\n    }\n}\n");

        // UIManager
        Write(Path.Combine(projectRoot, "Assets/Scripts/UI/UIManager.cs"),
"using UnityEngine;\nusing UnityEngine.UI;\nusing TMPro;\n\npublic class UIManager : MonoBehaviour\n{\n    public TextMeshProUGUI timerText;\n    public Button startPauseButton;\n    public TextMeshProUGUI startPauseButtonText;\n    public Button resetButton;\n    public TextMeshProUGUI focusPointsText;\n    public TextMeshProUGUI incomeRateText;\n    public TextMeshProUGUI statusText;\n    public Image backgroundPanel;\n    public Color idleColor = new Color(0.56f, 0.73f, 0.87f, 1f);\n    public Color workingColor = new Color(1f, 0.76f, 0.48f, 1f);\n    public Color completedColor = new Color(0.6f, 1f, 0.6f, 1f);\n\n    void Start()\n    {\n        if (startPauseButton != null) startPauseButton.onClick.AddListener(OnStartPauseClicked);\n        if (resetButton != null) resetButton.onClick.AddListener(OnResetClicked);\n        if (FocusSystem.Instance != null)\n        {\n            FocusSystem.Instance.OnTimerTick += UpdateTimerDisplay;\n            FocusSystem.Instance.OnFocusCompleted += OnFocusCompleted;\n            FocusSystem.Instance.OnRunningChanged += OnRunningChanged;\n        }\n        if (ResourceSystem.Instance != null)\n            ResourceSystem.Instance.OnFocusPointsChanged += UpdateFocusPoints;\n        UpdateTimerDisplay(FocusSystem.Instance.focusDurationMinutes * 60f, FocusSystem.Instance.focusDurationMinutes * 60f);\n        UpdateFocusPoints(0);\n        UpdateStatus(\"Idle\");\n        SetBackgroundColor(idleColor);\n    }\n\n    void Update()\n    {\n        if (incomeRateText != null && IdleSystem.Instance != null)\n            incomeRateText.text = \"+\" + IdleSystem.Instance.GetCurrentRate().ToString(\"F1\") + \"/s\";\n    }\n\n    void UpdateTimerDisplay(float remaining, float total)\n    {\n        if (timerText != null)\n            timerText.text = string.Format(\"{0:00}:{1:00}\", Mathf.FloorToInt(remaining / 60f), Mathf.FloorToInt(remaining % 60f));\n    }\n\n    void UpdateFocusPoints(float points)\n    {\n        if (focusPointsText != null) focusPointsText.text = Mathf.FloorToInt(points).ToString();\n    }\n\n    void OnStartPauseClicked() { if (FocusSystem.Instance != null) FocusSystem.Instance.ToggleTimer(); }\n    void OnResetClicked()\n    {\n        if (FocusSystem.Instance != null) FocusSystem.Instance.ResetTimer();\n        UpdateStatus(\"Idle\");\n        SetBackgroundColor(idleColor);\n    }\n\n    void OnRunningChanged(bool running)\n    {\n        if (startPauseButtonText != null) startPauseButtonText.text = running ? \"Pause\" : \"Start\";\n        if (running) { UpdateStatus(\"Focusing...\"); SetBackgroundColor(workingColor); }\n        else if (FocusSystem.Instance != null && !FocusSystem.Instance.IsCompleted) { UpdateStatus(\"Paused\"); SetBackgroundColor(idleColor); }\n    }\n\n    void OnFocusCompleted()\n    {\n        UpdateStatus(\"Session Complete! +100 FP\");\n        SetBackgroundColor(completedColor);\n        if (startPauseButtonText != null) startPauseButtonText.text = \"Start\";\n    }\n\n    void UpdateStatus(string text) { if (statusText != null) statusText.text = text; }\n    void SetBackgroundColor(Color color) { if (backgroundPanel != null) backgroundPanel.color = color; }\n\n    void OnDestroy()\n    {\n        if (FocusSystem.Instance != null)\n        {\n            FocusSystem.Instance.OnTimerTick -= UpdateTimerDisplay;\n            FocusSystem.Instance.OnFocusCompleted -= OnFocusCompleted;\n            FocusSystem.Instance.OnRunningChanged -= OnRunningChanged;\n        }\n        if (ResourceSystem.Instance != null)\n            ResourceSystem.Instance.OnFocusPointsChanged -= UpdateFocusPoints;\n    }\n}\n");

        // BuildScene editor script
        Write(Path.Combine(projectRoot, "Assets/Editor/BuildScene.cs"),
"using UnityEngine;\nusing UnityEditor;\nusing UnityEngine.UI;\nusing TMPro;\n\npublic class BuildScene\n{\n    [MenuItem(\"CozyIdle/Build Scene\")]\n    public static void Execute()\n    {\n        GameObject gm = GameObject.Find(\"GameManager\");\n        if (gm == null) gm = new GameObject(\"GameManager\");\n        AddComp<ResourceSystem>(gm);\n        AddComp<FocusSystem>(gm);\n        AddComp<IdleSystem>(gm);\n\n        GameObject canvasGO = GameObject.Find(\"UICanvas\");\n        if (canvasGO == null)\n        {\n            canvasGO = new GameObject(\"UICanvas\");\n            var c = canvasGO.AddComponent<Canvas>();\n            c.renderMode = RenderMode.ScreenSpaceOverlay;\n            c.sortingOrder = 100;\n            var cs = canvasGO.AddComponent<CanvasScaler>();\n            cs.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;\n            cs.referenceResolution = new Vector2(1920, 1080);\n            canvasGO.AddComponent<GraphicRaycaster>();\n        }\n\n        var bgPanel = MakeChild(\"BackgroundPanel\", canvasGO.transform);\n        var bgImg = AddComp<Image>(bgPanel);\n        bgImg.color = new Color(0.56f, 0.73f, 0.87f, 1f);\n        Stretch(bgPanel);\n\n        var container = MakeChild(\"MainContainer\", bgPanel.transform);\n        var cr = container.GetComponent<RectTransform>();\n        cr.anchorMin = new Vector2(0.25f, 0.1f);\n        cr.anchorMax = new Vector2(0.75f, 0.9f);\n        cr.offsetMin = Vector2.zero;\n        cr.offsetMax = Vector2.zero;\n        var vl = AddComp<VerticalLayoutGroup>(container);\n        vl.childAlignment = TextAnchor.MiddleCenter;\n        vl.spacing = 30f;\n        vl.childControlWidth = true;\n        vl.childControlHeight = false;\n        vl.childForceExpandWidth = true;\n        vl.childForceExpandHeight = false;\n\n        var statusGO = MakeTMP(\"StatusText\", container.transform, \"Idle\", 36); SetH(statusGO, 60);\n        var timerGO = MakeTMP(\"TimerText\", container.transform, \"25:00\", 96); SetH(timerGO, 120);\n\n        var btnBox = MakeChild(\"ButtonContainer\", container.transform);\n        var hl = AddComp<HorizontalLayoutGroup>(btnBox);\n        hl.childAlignment = TextAnchor.MiddleCenter;\n        hl.spacing = 20f;\n        hl.childControlWidth = false;\n        hl.childControlHeight = false;\n        SetH(btnBox, 70);\n\n        var startBtn = MakeBtn(\"StartPauseButton\", btnBox.transform, \"Start\", new Color(0.3f,0.7f,0.4f,1f), 200, 60);\n        var resetBtn = MakeBtn(\"ResetButton\", btnBox.transform, \"Reset\", new Color(0.8f,0.4f,0.4f,1f), 150, 60);\n\n        var sep = MakeChild(\"Separator\", container.transform); SetH(sep, 20);\n        var fpLabel = MakeTMP(\"FPLabel\", container.transform, \"Focus Points\", 28); SetH(fpLabel, 40);\n        var fpValue = MakeTMP(\"FocusPointsText\", container.transform, \"0\", 64); SetH(fpValue, 80);\n        var incomeGO = MakeTMP(\"IncomeRateText\", container.transform, \"+1.0/s\", 24); SetH(incomeGO, 40);\n        incomeGO.GetComponent<TextMeshProUGUI>().color = new Color(0.4f,0.4f,0.4f,1f);\n\n        var ui = AddComp<UIManager>(canvasGO);\n        ui.timerText = timerGO.GetComponent<TextMeshProUGUI>();\n        ui.startPauseButton = startBtn.GetComponent<Button>();\n        ui.startPauseButtonText = startBtn.GetComponentInChildren<TextMeshProUGUI>();\n        ui.resetButton = resetBtn.GetComponent<Button>();\n        ui.focusPointsText = fpValue.GetComponent<TextMeshProUGUI>();\n        ui.incomeRateText = incomeGO.GetComponent<TextMeshProUGUI>();\n        ui.statusText = statusGO.GetComponent<TextMeshProUGUI>();\n        ui.backgroundPanel = bgImg;\n\n        EditorUtility.SetDirty(canvasGO);\n        EditorUtility.SetDirty(gm);\n        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(\n            UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene());\n        Debug.Log(\"[CozyIdle] Phase 1 scene built!\");\n    }\n\n    static GameObject MakeChild(string n, Transform p)\n    {\n        var t = p.Find(n);\n        if (t != null) return t.gameObject;\n        var go = new GameObject(n, typeof(RectTransform));\n        go.transform.SetParent(p, false);\n        return go;\n    }\n\n    static GameObject MakeTMP(string n, Transform p, string txt, float size)\n    {\n        var go = MakeChild(n, p);\n        var tmp = AddComp<TextMeshProUGUI>(go);\n        tmp.text = txt;\n        tmp.fontSize = size;\n        tmp.alignment = TextAlignmentOptions.Center;\n        tmp.color = Color.white;\n        return go;\n    }\n\n    static GameObject MakeBtn(string n, Transform p, string label, Color col, float w, float h)\n    {\n        var go = MakeChild(n, p);\n        var img = AddComp<Image>(go);\n        img.color = col;\n        AddComp<Button>(go);\n        go.GetComponent<RectTransform>().sizeDelta = new Vector2(w, h);\n        var tgo = MakeChild(\"Text\", go.transform);\n        var tmp = AddComp<TextMeshProUGUI>(tgo);\n        tmp.text = label; tmp.fontSize = 28;\n        tmp.alignment = TextAlignmentOptions.Center;\n        tmp.color = Color.white;\n        Stretch(tgo);\n        return go;\n    }\n\n    static void Stretch(GameObject go)\n    {\n        var r = go.GetComponent<RectTransform>();\n        r.anchorMin = Vector2.zero; r.anchorMax = Vector2.one;\n        r.offsetMin = Vector2.zero; r.offsetMax = Vector2.zero;\n    }\n\n    static void SetH(GameObject go, float h)\n    {\n        var le = AddComp<LayoutElement>(go);\n        le.preferredHeight = h;\n    }\n\n    static T AddComp<T>(GameObject go) where T : Component\n    {\n        var c = go.GetComponent<T>();\n        return c != null ? c : go.AddComponent<T>();\n    }\n}\n");

        AssetDatabase.Refresh();
        Debug.Log("[CozyIdle] All scripts created! Refresh complete.");
    }

    static void CreateDir(string path)
    {
        if (!Directory.Exists(path)) Directory.CreateDirectory(path);
    }

    static void Write(string path, string content)
    {
        string dir = Path.GetDirectoryName(path);
        if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(path, content);
        Debug.Log("[CozyIdle] Written: " + path);
    }
}
